data-type.interface:
{attribute 'qualified_only'}
{IF COMPILERVERSION(>=, '3.5.2.0')}
{attribute 'm4export_hide'}
{END_IF}
TYPE MEMORY_AREA :
(
MEM_UNKNOWN := -1,
MEM_MEMORY,
MEM_INPUT,
MEM_OUTPUT,
MEM_RETAIN,
MEM_GLOBAL,
MEM_LOCAL
)INT;
END_TYPE

TYPE VAR_INFO :
STRUCT
{p 0}(*Address of variable: for bits, address of byte which bit is accessed *)
{IF COMPILERVERSION(>=, '3.5.1.0')}
{p 1}ByteAddress : __XWORD;
{ELSE}
{p 1}ByteAddress : DWORD;
{END_IF}
{p 2}(* Offset in Bytes.
If variable is global, the offset denotes a global offset in the specified area
If variable is local, the offset denotes a local offset in the scope (fb or function)*)
{p 5}ByteOffset : DINT;
{p 6}(* Number of Area.
Number of the area in runtime system. With AppGetAreaAddress you can get the real address of the area.
If variable is local, value is -1*)
{p 7}Area : INT;
{p 8}(* number of Bit in Bytes. For non-Bit Types this value is -1 *)
{p 9}BitNr : INT;
{p 10}(* size of variable in Bits *)
{p 11}BitSize : UDINT;
{p 12}(* bitaddress of variable (if variable is at %M/I/Q location) otherwise undefined*)
{p 13}BitAdress : UDINT;
{p 14}(* type class of variable *)
{p 15}TypeClass : __SYSTEM.TYPE_CLASS;
{p 16}(* type name (for userdeftypes : name of function block or type definition) *)
{IF COMPILERVERSION(>=, '3.5.1.0')}
{p 17}TypeName : STRING(79);
{ELSE}
{p 17}TypeName : STRING(39);
{END_IF}
{p 18}(* for arrays : number of base elements *)
{p 19}NumElements : UDINT;
{p 20}(* for arrays : type class of base type *)
{p 21}BaseTypeClass : __SYSTEM.TYPE_CLASS;
{p 22}(* for arrays : bit size of base element *)
{p 23}ElemBitSize : UDINT;
{p 24}(* area information : memory, input, output, retain, global, local *)
{p 25}MemoryArea : __SYSTEM.MEMORY_AREA;
{p 26}(* symbol name : input of operator as string: up to 39 characters*)
{p 27}Symbol : STRING(39);
{p 28}(* comment of variable *)
{p 29}Comment : STRING(79);
END_STRUCT
END_TYPE

method.interface:
{implicit on}
METHOD __GetInterfaceReference : BOOL
VAR_INPUT
	nInterfaceId : DINT;
	pRef : POINTER TO POINTER TO DWORD;
END_VAR
{implicit off}

{implicit on}
METHOD __GetInterfacePointer : BOOL
VAR_INPUT
	pRef : POINTER TO POINTER TO DWORD;
END_VAR
{implicit off}

pou.interface:
{implicit on}
{attribute 'hide'}
FUNCTION __CheckedInterfaceCast : BOOL
VAR_INPUT
nInterfaceId : DINT;
pRef : POINTER TO POINTER TO DWORD;
queryInterface : IQueryInterface;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
IF (queryInterface = 0) THEN
	__CheckedInterfaceCast := FALSE;
	pRef^ := 0;
ELSE
	__CheckedInterfaceCast := queryInterface.__GetInterfaceReference(nInterfaceId, pRef);
END_IF
{implicit off}

pou.interface:
{implicit on}
{attribute 'hide'}
FUNCTION __CheckedPointerCast : BOOL
VAR_INPUT
	pRef : POINTER TO POINTER TO DWORD;
	queryPointer : IQueryInterface;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
IF (queryPointer = 0) THEN
	__CheckedPointerCast := FALSE;
	pRef^ := 0;
ELSE
	__CheckedPointerCast := queryPointer.__GetInterfacePointer(pRef);
END_IF
{implicit off}

pou.interface:
{implicit on}
{attribute 'hide'}
FUNCTION __CompareInterfaces : BOOL
VAR_INPUT
ppi1 : POINTER TO POINTER TO ARRAY [0..0] OF POINTER TO POINTER TO DWORD;
ppi2 : POINTER TO POINTER TO ARRAY [0..0] OF POINTER TO POINTER TO DWORD;
END_VAR
VAR
pthis1 : POINTER TO POINTER TO ARRAY [0..0] OF POINTER TO POINTER TO DWORD;
pthis2 : POINTER TO POINTER TO ARRAY [0..0] OF POINTER TO POINTER TO DWORD;
{IF COMPILERVERSION(>=, '3.5.0.0')}
dwOffset1 : __XWORD;
dwOffset2 : __XWORD;
{END_IF}
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
IF (ppi1 = 0 AND ppi2 = 0) THEN
	__CompareInterfaces := TRUE;
ELSIF (ppi1 = 0 OR ppi2 = 0) THEN
	__CompareInterfaces := FALSE;
ELSE
{IF COMPILERVERSION(>=, '3.5.0.0')}
  {IF hasvalue(AddrSize, '8')}
    dwOffset1 := ppi1^^[0];
    dwOffset2 := ppi2^^[0];
    pthis1 := ppi1 - dwOffset1;
	  pthis2 := ppi2 - dwOffset2;
  {ELSE}
	  pthis1 := ppi1 - ppi1^^[0];
	  pthis2 := ppi2 - ppi2^^[0];
  {END_IF}
{ELSE}
	pthis1 := ppi1 - ppi1^^[0];
	pthis2 := ppi2 - ppi2^^[0];
{END_IF}

	__CompareInterfaces := pthis1 = pthis2;
END_IF
		{implicit off}

data-type.interface:
{implicit on}
{attribute 'qualified_only'}
{attribute 'linkalways'}
TYPE __DataSegmentFlags :
(
DA_Data 		:= 16#1,
DA_Constant 	:= 16#2,
DA_Input 		:= 16#4,
DA_Output 		:= 16#8,
DA_Memory 		:= 16#10,
DA_Retain 		:= 16#20,
DA_Code 		:= 16#40,
DA_Area 		:= 16#80,		// special flag to indicate an area segment
DA_Persistent 	:= 16#100
)UINT;
END_TYPE
{implicit off}

{implicit on}
{attribute 'linkalways'}
TYPE __DataSegments :
STRUCT
nNumOfSegments : DINT;
pDataSegments : POINTER TO __SegmentInfo;
END_STRUCT
END_TYPE
{implicit off}

{implicit on}
{attribute 'linkalways'}
TYPE __SegmentInfo :
STRUCT
{IF COMPILERVERSION(>=, '3.5.2.0')}
{attribute 'displaymode':='hex'}
{END_IF}
dsKindOf    : __DataSegmentFlags;
uiArea      : UINT;
udOffset 	: UDINT;
udSize 		: UDINT;
udHighestUsedAddress : UDINT;
END_STRUCT
END_TYPE
{implicit off}

